        if (availableSlotIndex != -1 && slot instanceof CraftingResultSlot) {

            ((SlotState) slot).apoli$setState(ModifyCraftingPower.MODIFIED_RESULT_STACK);
            mcp.applyAfterCraftingItemAction(reference);

        }

        return reference.get();

