                    }

                    if (currentResult.isAccepted() && !previousResult.isAccepted()) {
                        previousResult = currentResult;
                    }

                    else if (currentResult.shouldSwingHand() && !previousResult.shouldSwingHand()) {
                        previousResult = currentResult;
