        public boolean accepts(ServerWorld world, BlockPos pos, GameEvent event, GameEvent.Emitter emitter) {
            return entity.getWorld() == world
                && (shouldListenToBlockEvents(emitter, new CachedBlockPosition(world, pos, true))
