public static boolean namespacesLoaded(JsonObject jsonObject, Set<String> namespaces, boolean and) {

		JsonArray jsonArray = JsonHelper.getArray(jsonObject, "namespaces");
		for (JsonElement jsonElement : jsonArray) {
			if (jsonElement.isJsonPrimitive()) {
				if (namespaces.contains(jsonElement.getAsString()) != and) {
					return !and;
				}
			} else {
				throw new JsonParseException("Invalid " + jsonElement + " entry: expected a JSON string!");
			}
		}

		return and;

	}

public static boolean test(Identifier id, JsonObject jsonObject) {

		try {
			JsonArray conditions = JsonHelper.getArray(jsonObject, ResourceConditions.CONDITIONS_KEY, null);
			if (conditions == null) {
				return true;
			} else {
				return ResourceConditions.conditionsMatch(conditions, true);
			}
		} catch (RuntimeException e) {
			Apoli.LOGGER.error("There was a problem parsing the resource condition(s) of power file " + id + " (skipping): " + e.getMessage());
			return false;
		}

	}

public static void sortModifiers(List<EntityAttributeModifier> modifiers) {
        modifiers.sort(Comparator.comparing(e -> e.getOperation().getId()));
    }

public static double sortAndApplyModifiers(List<EntityAttributeModifier> modifiers, double baseValue) {
        sortModifiers(modifiers);
        return applyModifiers(modifiers, baseValue);
    }

public static double applyModifiers(List<EntityAttributeModifier> modifiers, double baseValue) {
        double currentValue = baseValue;
        if(modifiers != null) {
            for(EntityAttributeModifier modifier : modifiers) {
                switch(modifier.getOperation()) {
                    case ADDITION:
                        currentValue += modifier.getValue();
                        break;
                    case MULTIPLY_BASE:
                        currentValue += baseValue * modifier.getValue();
                        break;
                    case MULTIPLY_TOTAL:
                        currentValue *= (1 + modifier.getValue());
                        break;
                }
            }
        }
        return currentValue;
    }

