public static Comparison getFromString(String comparisonString) {
        switch(comparisonString) {
            case "==":
                return EQUAL;
            case "<":
                return LESS_THAN;
            case ">":
                return GREATER_THAN;
            case "<=":
                return LESS_THAN_OR_EQUAL;
            case ">=":
                return GREATER_THAN_OR_EQUAL;
            case "!=":
                return NOT_EQUAL;
        }
        return NONE;
    }

