public Scheduler() {
        ServerTickEvents.END_SERVER_TICK.register(m -> {
            this.currentTick = m.getTicks();
            List<Consumer<MinecraftServer>> runnables = this.taskQueue.remove(this.currentTick);
            if (runnables != null) for (int i = 0; i < runnables.size(); i++) {
                Consumer<MinecraftServer> runnable = runnables.get(i);
                runnable.accept(m);

                if(runnable instanceof Repeating) {// reschedule repeating tasks
                    Repeating repeating = ((Repeating) runnable);
                    if(repeating.shouldQueue(this.currentTick))
                        this.queue(runnable, ((Repeating) runnable).next);
                }
            }

        });
    }

public void queue(Consumer<MinecraftServer> task, int tick) {
        this.taskQueue.computeIfAbsent(this.currentTick + tick + 1, t -> new ArrayList<>()).add(task);
    }

public void repeating(Consumer<MinecraftServer> task, int tick, int interval) {
        this.repeatWhile(task, null, tick, interval);
    }

public void repeatWhile(Consumer<MinecraftServer> task, IntPredicate requeue, int tick, int interval) {
        this.queue(new Repeating(task, requeue, interval), tick);
    }

public void repeatN(Consumer<MinecraftServer> task, int times, int tick, int interval) {
        this.repeatWhile(task, new IntPredicate() {
            private int remaining = times;
            @Override
            public boolean test(int value) {
                return this.remaining-- > 0;
            }
        }, tick, interval);
    }

@Override
            public boolean test(int value) {
                return this.remaining-- > 0;
            }

private Repeating(Consumer<MinecraftServer> task, IntPredicate requeue, int interval) {
            this.task = task;
            this.requeue = requeue;
            this.next = interval;
        }

public boolean shouldQueue(int predicate) {
            if(this.requeue == null)
                return true;
            return this.requeue.test(predicate);
        }

@Override
        public void accept(MinecraftServer server) {
            this.task.accept(server);
        }

public static Collection<BlockPos> getPositions(BlockPos center, Shape shape, int radius) {
        Set<BlockPos> positions = new HashSet<>();
        for(int i = -radius; i <= radius; i++) {
            for(int j = -radius; j <= radius; j++) {
                for(int k = -radius; k <= radius; k++) {
                    if(shape == Shape.CUBE || shape == Shape.CHEBYSHEV
                            || (shape == Shape.SPHERE || shape == Shape.EUCLIDEAN)
                                && i * i + j * j + k * k <= radius * radius
                                // The radius can't be negative here (the loops aren't even entered in that case)
                                // so there's no behavior change from testing that sqrt(i*i + j*j + k*k) <= radius
                            || (Math.abs(i) + Math.abs(j) + Math.abs(k)) <= radius) {
                        positions.add(new BlockPos(center.add(i, j, k)));
                    }
                }
            }
        }
        return positions;
    }

public static Set<Entity> getEntities(Shape shape, World world, Vec3d center, double radius) {

        Set<Entity> entities = new HashSet<>();

        double diameter = radius * 2;
        double x, y, z;

        for (Entity entity : world.getNonSpectatingEntities(Entity.class, Box.of(center, diameter, diameter, diameter))) {

            x = Math.abs(entity.getX() - center.getX());
            y = Math.abs(entity.getY() - center.getY());
            z = Math.abs(entity.getZ() - center.getZ());

            if (getDistance(shape, x, y, z) < radius) {
                entities.add(entity);
            }

        }

        return entities;

    }

public static double getDistance(Shape shape, double xDistance, double yDistance, double zDistance){
        return switch (shape){
            case SPHERE, EUCLIDEAN -> Math.sqrt(xDistance * xDistance + yDistance * yDistance + zDistance * zDistance);
            case STAR, MANHATTAN -> xDistance + yDistance + zDistance;
            case CUBE, CHEBYSHEV -> Math.max(Math.max(xDistance, yDistance), zDistance);
        };
    }

private static Matrix3f getBaseTransformMatrixFromNormalizedDirectionVector(Vec3d vector, float yaw){
        double xX, xZ, // X vector
            zX = 0.0D, zY = vector.getY(), zZ = 0.0D; // Z vector

        if (Math.abs(zY) != 1.0F) { // Z not vertical, can infer X from it
            // Z
            zX = vector.getX();
            zZ = vector.getZ();
            // X (orthogonal to the projection of Z on the global XZ plane)
            xX = vector.getZ();
            xZ = -vector.getX();
            // Normalize X
            float xFactor = (float)(1 / Math.sqrt(xX * xX + xZ * xZ));
            xX *= xFactor;
            xZ *= xFactor;
        } else {
            // If the orientation vector points straight up or straight down, use the yaw to determine the X vector (it's "on the left")
            // The pitch doesn't affect the X vector as it's a rotation around that same vector
            float trigonometricYaw = -yaw * 0.0174532925F; // pi / 180 = 0.0174532925
            xX = MathHelper.cos(trigonometricYaw);
            xZ = -MathHelper.sin(trigonometricYaw);
        }

        Matrix3f res = new Matrix3f();
        // X
        res.set(0, 0, (float)xX);
        res.set(1, 0, 0.0F); // X vector is horizontal, set its Y component (a10 (mathematically a21)) to 0
        res.set(2, 0, (float)xZ);
        // Y (cross product of Z and X, simplified by the fact that X has a Y component of 0)
        res.set(0, 1, (float)(zY * xZ));
        res.set(1, 1, (float)(zZ * xX - zX * xZ));
        res.set(2, 1, (float)(-zY * xX));
        // Z
        res.set(0, 2, (float)zX);
        res.set(1, 2, (float)zY);
        res.set(2, 2, (float)zZ);
        return res;
    }

public static void transformVectorToBase(Vec3d baseForwardVector, Vector3f vector, float baseYaw, boolean normalizeBase) {

        double baseScaleD = baseForwardVector.length();
        if (baseScaleD <= 0.007D){ // tweak value if too high, may be a bit too aggressive
            vector.zero();
        } else {
            float baseScale = (float)baseScaleD;

            Vec3d normalizedBase = baseForwardVector.normalize(); // the function called below assumes the base is normalized to simplify calculations (Y calculated as cross product of Z and X guaranteed to be normalized if X and Z are normalized)

            Matrix3f transformMatrix = getBaseTransformMatrixFromNormalizedDirectionVector(normalizedBase, baseYaw);
            if (!normalizeBase) // if the base wasn't supposed to get normalized, re-scale to compensate for the prior normalization
                transformMatrix.scale(baseScale, baseScale, baseScale);
            vector.mulTranspose(transformMatrix); // matrix multiplication, vector is now in the new base :D
        }
    }

public void toGlobal(Vector3f vector, Entity entity){
        Vec3d baseForwardVector;

        switch (this){

            case WORLD:
                break;

            case LOCAL:
            case LOCAL_HORIZONTAL:
            case LOCAL_HORIZONTAL_NORMALIZED:
                baseForwardVector = entity.getRotationVector();
                if (this != LOCAL) // horizontal
                    baseForwardVector = new Vec3d(baseForwardVector.getX(), 0, baseForwardVector.getZ());
                transformVectorToBase(baseForwardVector, vector, entity.getYaw(), this == LOCAL_HORIZONTAL_NORMALIZED);
                break;

            case VELOCITY:
            case VELOCITY_NORMALIZED:
            case VELOCITY_HORIZONTAL:
            case VELOCITY_HORIZONTAL_NORMALIZED:
                baseForwardVector = entity.getVelocity();
                if (this == VELOCITY_HORIZONTAL || this == VELOCITY_HORIZONTAL_NORMALIZED)
                    baseForwardVector = new Vec3d(baseForwardVector.getX(), 0, baseForwardVector.getZ());
                transformVectorToBase(baseForwardVector, vector, entity.getYaw(), this == VELOCITY_NORMALIZED || this == VELOCITY_HORIZONTAL_NORMALIZED);
                break;
        }
    }

