public static boolean inSnow(World world, BlockPos... blockPositions) {
        return Arrays.stream(blockPositions)
            .anyMatch(blockPos -> {
                Biome biome = world.getBiome(blockPos).value();
                return biome.getPrecipitation(blockPos) == Biome.Precipitation.SNOW
                    && isRainingAndExposed(world, blockPos);
            });
    }

public static boolean inThunderstorm(World world, BlockPos... blockPositions) {
        return Arrays.stream(blockPositions)
            .anyMatch(blockPos -> world.isThundering() && isRainingAndExposed(world, blockPos));
    }

private static boolean isRainingAndExposed(World world, BlockPos blockPos) {
        return world.isRaining()
            && world.isSkyVisible(blockPos)
            && world.getTopPosition(Heightmap.Type.MOTION_BLOCKING, blockPos).getY() < blockPos.getY();
    }

public Modifier(IModifierOperation operation, SerializableData.Instance dataInstance) {
        this.operation = operation;
        this.dataInstance = dataInstance;
    }

public IModifierOperation getOperation() {
        return operation;
    }

public SerializableData.Instance getData() {
        return dataInstance;
    }

public double apply(Entity entity, double value) {
        return operation.apply(entity, List.of(dataInstance), value, value);
    }

@Override
    public int compareTo(@NotNull Modifier o) {
        if(o.operation == operation) {
            return 0;
        } else if(o.operation.getPhase() == operation.getPhase()) {
            return o.operation.getOrder() - operation.getOrder();
        } else {
            return o.operation.getPhase() == IModifierOperation.Phase.BASE ? 1 : -1;
        }
    }

ModifierOperation(Phase phase, int order, BlockStateVariantMap.TriFunction<List<Double>, Double, Double, Double> function) {
        this.phase = phase;
        this.order = order;
        this.function = function;
    }

@Override
    public Phase getPhase() {
        return phase;
    }

@Override
    public int getOrder() {
        return order;
    }

@Override
    public SerializableData getData() {
        return DATA;
    }

@Override
    public double apply(Entity entity, List<SerializableData.Instance> instances, double base, double current) {
        return function.apply(
            instances.stream()
                .map(instance -> {
                    double value = 0;
                    if(instance.isPresent("resource")) {
                        PowerHolderComponent component = PowerHolderComponent.KEY.get(entity);
                        PowerType<?> powerType = instance.get("resource");
                        if(!component.hasPower(powerType)) {
                            value = instance.get("value");
                        } else {
                            Power p = component.getPower(powerType);
                            if(p instanceof VariableIntPower vip) {
                                value = vip.getValue();
                            } else if(p instanceof CooldownPower cp) {
                                value = cp.getRemainingTicks();
                            }
                        }
                    } else {
                        value = instance.get("value");
                    }
                    if(instance.isPresent("modifier")) {
                        List<Modifier> modifiers = instance.get("modifier");
                        value = ModifierUtil.applyModifiers(entity, modifiers, value);
                    }
                    return value;
                })
                .collect(Collectors.toList()),
            base, current);
    }

public static void registerAll() {
        for(ModifierOperation operation : ModifierOperation.values()) {
            Registry.register(ApoliRegistries.MODIFIER_OPERATION,
                Apoli.identifier(operation.toString().toLowerCase(Locale.ROOT)),
                operation);
        }
    }

public static Modifier createSimpleModifier(IModifierOperation operation, double value) {
        SerializableData.Instance data = ModifierOperation.DATA.new Instance();
        data.set("value", value);
        data.set("resource", null);
        data.set("modifier", null);
        return new Modifier(operation, data);
    }

public static Modifier fromAttributeModifier(EntityAttributeModifier attributeModifier) {
        IModifierOperation operation = null;
        switch(attributeModifier.getOperation()) {
            case ADDITION -> operation = ModifierOperation.ADD_BASE_EARLY;
            case MULTIPLY_BASE -> operation = ModifierOperation.MULTIPLY_BASE_ADDITIVE;
            case MULTIPLY_TOTAL -> operation = ModifierOperation.MULTIPLY_TOTAL_MULTIPLICATIVE;
        }
        if(operation == null) {
            throw new RuntimeException(
                "Could not construct generic modifier from attribute modifier. Unknown operation: "
                    + attributeModifier.getOperation());
        }
        return createSimpleModifier(operation, attributeModifier.getValue());
    }

public static Map<IModifierOperation, List<SerializableData.Instance>> sortModifiers(List<Modifier> modifiers) {
        Map<IModifierOperation, List<SerializableData.Instance>> buckets = new HashMap<>();
        for(Modifier modifier : modifiers) {
            List<SerializableData.Instance> list = buckets.computeIfAbsent(modifier.getOperation(), op -> new LinkedList<>());
            list.add(modifier.getData());
        }
        return buckets;
    }

public static double applyModifiers(Entity entity, List<Modifier> modifiers, double baseValue) {
        return applyModifiers(entity, sortModifiers(modifiers), baseValue);
    }

public static double applyModifiers(Entity entity, Map<IModifierOperation, List<SerializableData.Instance>> modifiers, double baseValue) {
        double currentBase = baseValue;
        double currentValue = baseValue;
        List<IModifierOperation> operations = new LinkedList<>(modifiers.keySet());
        operations.sort(((o1, o2) -> {
            if(o1 == o2) {
                return 0;
            } else if(o1.getPhase() == o2.getPhase()) {
                return o1.getOrder() - o2.getOrder();
            } else {
                return o1.getPhase().ordinal() - o2.getPhase().ordinal();
            }
        }));
        IModifierOperation.Phase lastPhase = IModifierOperation.Phase.BASE;
        for(IModifierOperation op : operations) {
            List<SerializableData.Instance> data = modifiers.get(op);
            if(op.getPhase() != lastPhase) {
                currentBase = currentValue;
            }
            currentValue = op.apply(entity, data, currentBase, currentValue);
        }
        return currentValue;
    }
